    how3: "समस्या की पहचान वाले कदम में पहले 4W (कौन, क्या, कहाँ, क्यों) भरिए, फिर समस्या कथन का साँचा। “4W से खाली जगह भरें” दबाने से पहला ड्राफ़्ट तुरंत बन जाता है।",
    how4: "कक्षा गतिविधि: हर समूह को अपने इलाके की एक असली समस्या दीजिए (स्कूल गेट पर ट्रैफ़िक, प्लास्टिक कचरा, देर से आने वाली बस)। समूह दो पीरियड में कैनवस पूरा करें और 3 मिनट में प्रस्तुत करें।",
    how5: "“पूरा कैनवस” खोलकर प्रिंट कीजिए, टेक्स्ट फ़ाइल डाउनलोड कीजिए या स्मार्टबोर्ड पर दिखाइए। प्रोजेक्ट को दूसरे डिवाइस पर ले जाने के लिए एक्सपोर्ट और इम्पोर्ट का इस्तेमाल कीजिए।",
    inside_title: "AI प्रोजेक्ट साइकिल क्या है?",
    inside_text: "यह वह कदम-दर-कदम योजना है जिसे AI बनाने वाले अपनाते हैं: समस्या को समझना (Problem Scoping), डेटा जुटाना (Data Acquisition), चार्ट से डेटा को परखना (Data Exploration), मॉडल बनाना (Modelling), जाँचना कि वह कितना अच्छा काम करता है (Evaluation) और उसे असल में इस्तेमाल में लाना (Deployment)। हर कदम पर नैतिकता की जाँच होती है। यह ऐप खुद AI का इस्तेमाल नहीं करता: यह आपकी टीम को एक असली AI प्रोजेक्ट टीम की तरह सोचने में मदद करता है।",
