    tt2: "हर पीरियड में एक चरण: पहले पीरियड में समस्या की पहचान, दूसरे में डेटा और उसकी जाँच-परख, तीसरे में मॉडल, मूल्यांकन और नैतिकता, चौथे में प्रस्तुति।",
