    st1_d: "AI-এর কথা ভাবার আগে সমস্যাটা ভালো করে বুঝুন। 4W ক্যানভাস ব্যবহার করুন: কে, কী, কোথায় আর কেন।",
    st2_d: "ঠিক করুন কোন ডেটা লাগবে আর তা কোথা থেকে আসবে। ভালো AI মডেলের জন্য ভালো, নির্ভরযোগ্য ডেটা দরকার।",
    st3_d: "চার্ট দিয়ে ডেটা কীভাবে খুঁটিয়ে দেখবেন তার পরিকল্পনা করুন, যাতে প্যাটার্ন, ভুল আর অবাক করা তথ্য ধরা পড়ে।",
    st4_d: "বেছে নিন যন্ত্র কীভাবে সিদ্ধান্ত নেবে: মানুষের লেখা নিয়ম দিয়ে, নাকি অনেক উদাহরণ থেকে শিখে।",
    st5_d: "মডেলকে এমন নতুন ডেটায় পরীক্ষা করুন যা সে আগে দেখেনি, আর ঠিক করুন সাফল্য কীভাবে মাপবেন।",
    st6_d: "পরিকল্পনা করুন সত্যিকারের মানুষ আপনার সমাধান কীভাবে ব্যবহার করবেন এবং কে এর দেখাশোনা করবেন।",
    st7_d: "যাচাই করুন আপনার প্রজেক্ট গোপনীয়তাকে সম্মান করে, সবার প্রতি ন্যায্য এবং নিরাপদ।",
