    st2_d: "ਤੈਅ ਕਰੋ ਕਿ ਕਿਹੜਾ ਡਾਟਾ ਚਾਹੀਦਾ ਹੈ ਅਤੇ ਉਹ ਕਿੱਥੋਂ ਆਵੇਗਾ। ਚੰਗੇ AI ਮਾਡਲ ਲਈ ਚੰਗਾ, ਭਰੋਸੇਯੋਗ ਡਾਟਾ ਜ਼ਰੂਰੀ ਹੈ।",
