    intro: "CBSE ଢଙ୍ଗରେ ନିଜର AI ପ୍ରୋଜେକ୍ଟ ଯୋଜନା କରନ୍ତୁ: 4W ଦ୍ୱାରା ସମସ୍ୟା ବୁଝନ୍ତୁ, ଡାଟା, ମଡେଲ ଓ ମୂଲ୍ୟାଙ୍କନର ଯୋଜନା କରନ୍ତୁ, ନୈତିକତା ଯାଞ୍ଚ କରନ୍ତୁ, ତା’ପରେ କ୍ୟାନଭାସ ପ୍ରିଣ୍ଟ କରନ୍ତୁ।",
