    how2: "ପାହାଚ ପରେ ପାହାଚ ଆଗକୁ ବଢ଼ନ୍ତୁ। ପ୍ରତ୍ୟେକ ପ୍ରଶ୍ନର ଉତ୍ତର ନିଜ ଭାଷାରେ, ଯେକୌଣସି ଭାଷାରେ ଲେଖନ୍ତୁ। ସବୁକିଛି ଏହି ଡିଭାଇସରେ ଆପେଆପେ ସେଭ ହୁଏ।",
    how3: "ସମସ୍ୟା ଚିହ୍ନଟ ପାହାଚରେ ପ୍ରଥମେ 4W (କିଏ, କ’ଣ, କେଉଁଠି, କାହିଁକି) ଭରନ୍ତୁ, ତା’ପରେ ସମସ୍ୟା ବିବୃତିର ଢାଞ୍ଚା। “4W ରୁ ଖାଲି ସ୍ଥାନ ଭରନ୍ତୁ” ଦବାଇଲେ ପ୍ରଥମ ଡ୍ରାଫ୍ଟ ତୁରନ୍ତ ତିଆରି ହୁଏ।",
    how4: "ଶ୍ରେଣୀ କାର୍ଯ୍ୟ: ପ୍ରତ୍ୟେକ ଦଳକୁ ନିଜ ଅଞ୍ଚଳର ଗୋଟିଏ ପ୍ରକୃତ ସମସ୍ୟା ଦିଅନ୍ତୁ (ସ୍କୁଲ ଫାଟକରେ ଟ୍ରାଫିକ, ପ୍ଲାଷ୍ଟିକ ଅଳିଆ, ବିଳମ୍ବରେ ଆସୁଥିବା ବସ)। ଦଳମାନେ ଦୁଇ ପିରିୟଡରେ କ୍ୟାନଭାସ ସାରି 3 ମିନିଟରେ ଉପସ୍ଥାପନ କରିବେ।",
    how5: "“ପୂରା କ୍ୟାନଭାସ” ଖୋଲି ପ୍ରିଣ୍ଟ କରନ୍ତୁ, ଟେକ୍ସଟ ଭାବେ ଡାଉନଲୋଡ କରନ୍ତୁ କିମ୍ବା ସ୍ମାର୍ଟବୋର୍ଡରେ ଦେଖାନ୍ତୁ। ପ୍ରୋଜେକ୍ଟକୁ ଅନ୍ୟ ଡିଭାଇସକୁ ନେବାକୁ ଏକ୍ସପୋର୍ଟ ଓ ଇମ୍ପୋର୍ଟ ବ୍ୟବହାର କରନ୍ତୁ।",
    inside_title: "AI ପ୍ରୋଜେକ୍ଟ ସାଇକେଲ କ’ଣ?",
    inside_text: "ଏହା ସେହି ପାହାଚ-ପାହାଚ ଯୋଜନା ଯାହା AI ନିର୍ମାତାମାନେ ଅନୁସରଣ କରନ୍ତି: ସମସ୍ୟା ବୁଝିବା (Problem Scoping), ଡାଟା ସଂଗ୍ରହ (Data Acquisition), ଚାର୍ଟ ସାହାଯ୍ୟରେ ଡାଟା ଅନୁଧ୍ୟାନ (Data Exploration), ମଡେଲ ତିଆରି (Modelling), ଏହା କେତେ ଭଲ କାମ କରେ ତାହା ଯାଞ୍ଚ (Evaluation) ଏବଂ ପ୍ରକୃତ ବ୍ୟବହାରରେ ଲଗାଇବା (Deployment)। ପ୍ରତ୍ୟେକ ପାହାଚରେ ନୈତିକତା ଯାଞ୍ଚ ହୁଏ। ଏହି ଆପ୍ ନିଜେ AI ବ୍ୟବହାର କରେ ନାହିଁ: ଏହା ଆପଣଙ୍କ ଦଳକୁ ପ୍ରକୃତ AI ପ୍ରୋଜେକ୍ଟ ଦଳ ପରି ଚିନ୍ତା କରିବାରେ ସାହାଯ୍ୟ କରେ।",
    teacher_title: "ଦଳଗତ କାମ ପାଇଁ ଶିକ୍ଷକଙ୍କ ପରାମର୍ଶ",
    tt1: "4–5 ଜଣିଆ ଦଳ କରନ୍ତୁ ଓ ଭୂମିକା ଦିଅନ୍ତୁ: ଲିଡର (ସମୟ ଧ୍ୟାନ ରଖେ), ଗବେଷକ, ଡାଟା ସଂଗ୍ରାହକ, ଡିଜାଇନର (ଚାର୍ଟ ଓ କ୍ୟାନଭାସ) ଏବଂ ଉପସ୍ଥାପକ। ପରବର୍ତ୍ତୀ ପ୍ରୋଜେକ୍ଟରେ ଭୂମିକା ବଦଳାନ୍ତୁ।",
    tt2: "ପ୍ରତି ପିରିୟଡରେ ଗୋଟିଏ ପର୍ଯ୍ୟାୟ: ପ୍ରଥମ ପିରିୟଡରେ ସମସ୍ୟା ଚିହ୍ନଟ, ଦ୍ୱିତୀୟରେ ଡାଟା ଓ ତାର ଅନୁଧ୍ୟାନ, ତୃତୀୟରେ ମଡେଲ, ମୂଲ୍ୟାଙ୍କନ ଓ ନୈତିକତା, ଚତୁର୍ଥରେ ଉପସ୍ଥାପନା।",
    tt3: "ସ୍ମାର୍ଟବୋର୍ଡରେ ଗୋଟିଏ ନମୁନା ପ୍ରୋଜେକ୍ଟରୁ ଆରମ୍ଭ କରନ୍ତୁ। ଶ୍ରେଣୀକୁ ପଚାରନ୍ତୁ: ସମସ୍ୟା କାହାର? ସମସ୍ୟା କ’ଣ? କେଉଁଠି ହୁଏ? ଏହା କାହିଁକି ଗୁରୁତ୍ୱପୂର୍ଣ୍ଣ?",
    tt4: "ଗ୍ୟାଲେରି ୱାକ: ପ୍ରତ୍ୟେକ ଦଳର କ୍ୟାନଭାସ ପ୍ରିଣ୍ଟ କରି କାନ୍ଥରେ ଲଗାନ୍ତୁ। ଅନ୍ୟ ଦଳମାନେ କାଗଜ ଚିରକୁଟରେ ଗୋଟିଏ ପ୍ରଶଂସା ଓ ଗୋଟିଏ ପ୍ରଶ୍ନ ଲେଖି ଲଗାଇବେ।",
    tt5: "ନୈତିକତାର ପାରସ୍ପରିକ ସମୀକ୍ଷା: ଦଳମାନେ କ୍ୟାନଭାସ ଅଦଳବଦଳ କରି ଅନ୍ୟ ଦଳର ପ୍ରୋଜେକ୍ଟର ନୈତିକତା ଯାଞ୍ଚ କରିବେ।",
    tt6: "ଡିଭାଇସ କମ୍? “ପୂରା କ୍ୟାନଭାସ” ପାହାଚରେ “ଖାଲି ୱାର୍କସିଟ୍ ପ୍ରିଣ୍ଟ କରନ୍ତୁ” ବ୍ୟବହାର କରନ୍ତୁ ଓ ଦଳମାନଙ୍କୁ ହାତରେ ଭରିବାକୁ ଦିଅନ୍ତୁ। ସହଜ ନମ୍ବର: ସମସ୍ୟା, ଡାଟା, ମଡେଲ, ମୂଲ୍ୟାଙ୍କନ ଓ ନୈତିକତାକୁ 2 ନମ୍ବର ଲେଖାଏଁ।",
