    st8: "ପୂରା କ୍ୟାନଭାସ",
    st1_d: "AI ବିଷୟରେ ଭାବିବା ଆଗରୁ ସମସ୍ୟାକୁ ଭଲ ଭାବେ ବୁଝନ୍ତୁ। 4W କ୍ୟାନଭାସ ବ୍ୟବହାର କରନ୍ତୁ: କିଏ, କ’ଣ, କେଉଁଠି ଓ କାହିଁକି।",
    st2_d: "କେଉଁ ଡାଟା ଦରକାର ଓ ତାହା କେଉଁଠୁ ଆସିବ ସ୍ଥିର କରନ୍ତୁ। ଭଲ AI ମଡେଲ ପାଇଁ ଭଲ, ବିଶ୍ୱସନୀୟ ଡାଟା ଦରକାର।",
    st3_d: "ଚାର୍ଟ ସାହାଯ୍ୟରେ ଡାଟା କିପରି ଅନୁଧ୍ୟାନ କରିବେ ତାହାର ଯୋଜନା କରନ୍ତୁ, ଯେପରି ପାଟର୍ନ, ଭୁଲ ଓ ଆଶ୍ଚର୍ଯ୍ୟଜନକ କଥା ଦେଖାଯିବ।",
    st4_d: "ଯନ୍ତ୍ର କିପରି ନିଷ୍ପତ୍ତି ନେବ ବାଛନ୍ତୁ: ଲୋକମାନେ ଲେଖିଥିବା ନିୟମରେ, ନା ଅନେକ ଉଦାହରଣରୁ ଶିଖି।",
    st5_d: "ମଡେଲ କେବେ ଦେଖିନଥିବା ନୂଆ ଡାଟାରେ ତାକୁ ପରୀକ୍ଷା କରନ୍ତୁ, ଏବଂ ସଫଳତା କିପରି ମାପିବେ ସ୍ଥିର କରନ୍ତୁ।",
    st6_d: "ପ୍ରକୃତ ଲୋକମାନେ ଆପଣଙ୍କ ସମାଧାନ କିପରି ବ୍ୟବହାର କରିବେ ଓ କିଏ ଏହାର ଯତ୍ନ ନେବ, ତାହାର ଯୋଜନା କରନ୍ତୁ।",
    st7_d: "ଯାଞ୍ଚ କରନ୍ତୁ ଯେ ଆପଣଙ୍କ ପ୍ରୋଜେକ୍ଟ ଗୋପନୀୟତାକୁ ସମ୍ମାନ କରେ, ସମସ୍ତଙ୍କ ପ୍ରତି ନ୍ୟାୟପୂର୍ଣ୍ଣ ଓ ସୁରକ୍ଷିତ।",
