    st1: "சிக்கல் வரையறை",
    st2: "தரவு சேகரிப்பு",
    st3: "தரவு ஆய்வு",
    st4: "மாதிரி உருவாக்கம்",
    st5: "மதிப்பீடு",
    st6: "பயன்பாட்டுக்குக் கொண்டுவருதல்",
    st7: "அறநெறிச் சோதனை",
    st8: "முழு கேன்வாஸ்",
    st1_d: "AI பற்றி யோசிக்கும் முன் சிக்கலை நன்றாகப் புரிந்துகொள்ளுங்கள். 4W கேன்வாஸைப் பயன்படுத்துங்கள்: யார், என்ன, எங்கே, ஏன்.",
    st2_d: "எந்தத் தரவு தேவை, அது எங்கிருந்து வரும் என்று முடிவு செய்யுங்கள். நல்ல AI மாதிரிக்கு நல்ல, நம்பகமான தரவு தேவை.",
    st3_d: "வடிவங்கள், தவறுகள், வியப்பான விஷயங்கள் தெரியும்படி, வரைபடங்களால் தரவை எப்படி ஆராய்வீர்கள் என்று திட்டமிடுங்கள்.",
    st4_d: "இயந்திரம் எப்படி முடிவெடுக்கும் என்று தேர்ந்தெடுங்கள்: மனிதர்கள் எழுதும் விதிகளால், அல்லது பல எடுத்துக்காட்டுகளிலிருந்து கற்று.",
    st5_d: "மாதிரி இதுவரை பார்க்காத புதிய தரவில் அதைச் சோதியுங்கள், வெற்றியை எப்படி அளப்பீர்கள் என்று முடிவு செய்யுங்கள்.",
    st6_d: "உண்மையான மக்கள் உங்கள் தீர்வை எப்படிப் பயன்படுத்துவார்கள், யார் அதைப் பராமரிப்பார்கள் என்று திட்டமிடுங்கள்.",
    st7_d: "உங்கள் திட்டம் தனியுரிமையை மதிக்கிறதா, எல்லோருக்கும் நியாயமானதா, பாதுகாப்பானதா என்று சோதியுங்கள்.",
    st8_d: "முழுத் திட்டமும் ஒரே பக்கத்தில்: பாருங்கள், அச்சிடுங்கள், பதிவிறக்குங்கள் அல்லது வழங்குங்கள்.",
    w_who: "யார்?",
    w_what: "என்ன?",
    w_where: "எங்கே?",
    w_why: "ஏன்?",
    q_who: "பங்குதாரர்கள் யார்? (இந்தச் சிக்கலை எதிர்கொள்பவர்கள் அல்லது இதனால் பாதிக்கப்படுபவர்கள்)",
    q_who_know: "அவர்களைப் பற்றி உங்களுக்கு என்ன தெரியும்?",
    q_what: "சிக்கல் என்ன?",
    q_what_evidence: "இது உண்மையிலேயே சிக்கல் என்று உங்களுக்கு எப்படித் தெரியும்? ஏதேனும் சான்று உண்டா?",
    q_where: "பங்குதாரர்கள் எந்தச் சூழலில் இந்தச் சிக்கலை எதிர்கொள்கிறார்கள்? இது எங்கே, எப்போது நடக்கிறது?",
    q_why_value: "பங்குதாரர்களுக்கு மிக மதிப்பானது எதுவாக இருக்கும்?",
    q_why_improve: "அது அவர்களின் நிலையை எப்படி மேம்படுத்தும்?",
    ps_h: "சிக்கல் அறிக்கை வார்ப்புரு",
    ps_help: "எங்கள் [பங்குதாரர்கள்] ஒரு சிக்கலைச் சந்திக்கிறார்கள்: [பிரச்சினை, தேவை]. இது நடக்கும் சூழல்: [சூழல், நிலைமை]. ஒரு சிறந்த தீர்வு [அவர்களுக்கு என்ன நன்மை செய்யும்].",
    ps_l_who: "பங்குதாரர்கள் (யார்)",
    ps_l_what: "பிரச்சினை அல்லது தேவை (என்ன)",
    ps_l_where: "சூழல் அல்லது நிலைமை (எங்கே)",
    ps_l_why: "அவர்களுக்கான நன்மை (ஏன்)",
    ps_fill: "4W-இலிருந்து வெற்றிடங்களை நிரப்பு",
    ps_fill_none: "நிரப்ப எதுவும் இல்லை: வெற்றிடங்கள் ஏற்கெனவே நிரம்பியுள்ளன அல்லது 4W காலியாக உள்ளது.",
    ps_preview: "எங்கள் சிக்கல் அறிக்கை",
    ps_empty: "உங்கள் சிக்கல் அறிக்கையை இங்கே பார்க்க நான்கு வெற்றிடங்களையும் நிரப்புங்கள்.",
    ps_sentence: "எங்கள் {who} ஒரு சிக்கலைச் சந்திக்கிறார்கள்: {what}. இது நடக்கும் சூழல்: {where}. ஒரு சிறந்த தீர்வு {why}.",
    q_features: "உங்களுக்கு என்ன தரவு தேவை? தரவின் அம்சங்களை (features) எழுதுங்கள், ஒரு வரிக்கு ஒன்று.",
