    q_source_details: "விவரம்: எந்தத் தரவை யார், எப்படி, எத்தனை நாள் சேகரிப்பார்கள்?",
    q_data_check: "தரவு சரியானது, போதுமானது, நியாயமானது என்று எப்படி உறுதி செய்வீர்கள்?",
    scrape_h: "தரவைச் சரியான முறையில் சேகரியுங்கள்",
    scrape1: "முதலில் திறந்த தரவைத் தேடுங்கள்: data.gov.in, மக்கள்தொகைக் கணக்கெடுப்பு, IMD வானிலைத் தரவு, உங்கள் பள்ளியின் சொந்தப் பதிவுகள்.",
    scrape2: "வலை ஸ்கிராப்பிங் செய்யும் முன் இணையதளத்தின் விதிமுறைகளையும் அதன் robots.txt கோப்பையும் படியுங்கள், அதிகமான கோரிக்கைகளை அனுப்பாதீர்கள்.",
    scrape3: "அனுமதி இல்லாமல் யாருடைய தனிப்பட்ட விவரங்களையும் (பெயர், தொலைபேசி எண், முகப் புகைப்படம்) ஒருபோதும் சேகரிக்காதீர்கள்.",
    scrape4: "ஒவ்வொரு தரவும் எங்கிருந்து வந்தது என்று எழுதி வையுங்கள், மூலத்துக்கு நன்றி தெரிவியுங்கள்.",
    charts_h: "தரவை ஆராய எந்த வரைபடங்களைப் பயன்படுத்துவீர்கள்?",
