    chu_table: "துல்லியமான எண்கள்",
    q_explore_q: "தரவிடம் என்ன கேள்விகள் கேட்பீர்கள்? என்ன வடிவங்கள் கிடைக்கும் என்று எதிர்பார்க்கிறீர்கள்?",
    q_explore_notes: "குறிப்புகள்: விடுபட்ட அல்லது தவறான மதிப்புகள், வியப்பான விஷயங்கள், சுத்தம் செய்யும் படிகள்",
    approach_h: "மாதிரி உருவாக்க எந்த முறை?",
    ap_rule: "விதி அடிப்படை",
    ap_learn: "கற்றல் அடிப்படை",
    ap_rule_d: "மனிதர்கள் விதிகளை எழுதுகிறார்கள் (என்றால் … அப்போது …). விதிகள் குறைவாகவும் தெளிவாகவும் இருந்தால் நல்லது. இயந்திரம் தானாகக் கற்பதில்லை.",
    ap_learn_d: "இயந்திரம் பல எடுத்துக்காட்டுகளிலிருந்து (தரவு) வடிவங்களைக் கற்கிறது. புகைப்படம், பேச்சு போல விதி எழுதக் கடினமானபோது நல்லது. நிறைய நல்ல தரவு தேவை.",
    task_h: "மாதிரி எதைச் செய்யக் கற்கும்?",
