    tk_cluster: "கொத்தாக்கம் (clustering): லேபிள் இல்லாமல் குழுக்களைக் கண்டறிதல்",
    tk_unsure: "இன்னும் உறுதியில்லை",
    q_model_reason: "இந்த முறையை ஏன் தேர்ந்தெடுத்தீர்கள்?",
    q_model_how_rule: "உங்கள் விதிகளை எழுதுங்கள் (என்றால் … அப்போது …).",
    q_model_how_learn: "இயந்திரம் எந்த எடுத்துக்காட்டுகளிலிருந்து (பயிற்சித் தரவு) கற்கும்? உள்ளீடு என்ன, வெளியீடு என்ன?",
    q_model_how_none: "உங்கள் மாதிரி எப்படி வேலை செய்யும்? (விதிகள் அல்லது பயிற்சி எடுத்துக்காட்டுகள்)",
    tools_tip: "முயற்சிக்க இலவசக் கருவிகள்: புகைப்படங்களுக்கும் ஒலிகளுக்கும் Teachable Machine, அட்டவணைகளுக்கு விரிதாள் அல்லது Orange, மேல் வகுப்புகளுக்கு scikit-learn உடன் Python.",
    tools_link: "எங்கள் Teachable Machine செயலியைத் திறங்கள்",
    q_test_plan: "மாதிரியை எப்படிச் சோதிப்பீர்கள்? (கற்கும்போது மாதிரி ஒருபோதும் பார்க்காத சில தரவைத் தனியாக வையுங்கள்.)",
    metrics_h: "மாதிரி எவ்வளவு நல்லது என்று எப்படி அளப்பீர்கள்?",
    m_accuracy: "துல்லியம் (Accuracy)",
    m_precision: "நுட்பம் (Precision)",
    m_recall: "மீட்பு (Recall)",
    m_f1: "F1 மதிப்பெண்",
    m_error: "சராசரிப் பிழை",
    m_users: "பயனர் கருத்து",
    m_impact: "நிஜ வாழ்க்கைத் தாக்கம்",
    md_accuracy: "எல்லாப் பதில்களிலும் எத்தனை சரி",
    md_precision: "“ஆம்” என்று சொன்னபோது எத்தனை முறை சரி",
    md_recall: "உண்மையான “ஆம்” நிகழ்வுகளில் எத்தனையைப் பிடித்தது",
    md_f1: "நுட்பத்தையும் மீட்பையும் சமன்செய்யும் ஒரே எண்",
    md_error: "கணித்த எண்கள் உண்மை எண்களிலிருந்து எவ்வளவு தொலைவு",
    md_users: "மக்களுக்கு இது பயனுள்ளதாகவும் எளிதாகவும் இருக்கிறதா?",
    md_impact: "சிக்கல் உண்மையில் குறைந்ததா?",
    fpfn: "தவறான நேர்மறை (false positive) = பொய் எச்சரிக்கை (மாதிரி “ஆம்” என்கிறது, உண்மை “இல்லை”). தவறான எதிர்மறை (false negative) = தவறவிட்ட நிகழ்வு (மாதிரி “இல்லை” என்கிறது, உண்மை “ஆம்”).",
    cm_link: "எங்கள் Confusion Matrix ஆய்வகச் செயலியில் பயிற்சி செய்யுங்கள்",
    q_success: "எந்த முடிவை வெற்றியாகக் கருதுவீர்கள்?",
    q_error_cost: "மாதிரி தவறினால் என்ன நடக்கும்? எந்தத் தவறு மோசமானது: பொய் எச்சரிக்கையா, தவறவிட்ட நிகழ்வா?",
    q_deploy_how: "மக்கள் உங்கள் தீர்வை எப்படிப் பயன்படுத்துவார்கள்? (செயலி, இணையதளம், சாதனம், SMS, அறிவிப்புப் பலகை …)",
    q_deploy_care: "யார் இதைப் பராமரிப்பார்கள்? கருத்துகளை எப்படிப் பெற்று இதை மேம்படுத்துவீர்கள்?",
    eth_checks_h: "அறநெறிச் சரிபார்ப்புப் பட்டியல்: உங்கள் திட்டத்துக்கு உண்மையானவற்றைக் குறியிடுங்கள்",
    ec1: "உண்மையில் தேவையான அளவு தரவை மட்டுமே சேகரிக்கிறோம்.",
    ec2: "தரவு சேகரிக்கும் முன் மக்கள் அனுமதி (ஒப்புதல்) தருகிறார்கள்.",
    ec3: "தனிப்பட்ட தரவு பாதுகாப்பாக வைக்கப்படுகிறது, யாருடனும் பகிரப்படுவதில்லை.",
    ec4: "எங்கள் தரவில் எல்லா வகை மக்களும் உள்ளனர்: பெண்களும் ஆண்களும், கிராமங்களும் நகரங்களும், பல மொழிகளும்.",
    ec5: "மாதிரி வெவ்வேறு குழுக்களுக்குச் சமமாக நன்றாக வேலை செய்கிறதா என்று சோதிக்கிறோம்.",
    ec6: "முக்கிய முடிவுகளை ஒரு மனிதர் சரிபார்க்கிறார்; AI தனியாக முடிவெடுப்பதில்லை.",
    ec7: "AI பயன்படுத்தப்படுகிறது என்றும் அது என்ன செய்கிறது என்றும் பயனர்களுக்குச் சொல்லப்படுகிறது.",
    ec8: "என்ன தவறு நடக்கலாம், தீங்கை எப்படித் தடுப்பது என்று யோசித்துள்ளோம்.",
    eth_score: "{total}-இல் {n} குறியிடப்பட்டன",
    eth_ok: "அருமை! உங்கள் திட்டம் அறநெறிச் சோதனையில் தேறியது.",
    eth_todo: "குறியிடாதவற்றைப் பற்றிக் குழுவுடன் பேசி, உங்கள் திட்டத்தை மேம்படுத்துங்கள்.",
    q_eth_privacy: "தனியுரிமை: என்ன தனிப்பட்ட தரவு உள்ளது, அதை எப்படிப் பாதுகாப்பீர்கள்?",
    q_eth_bias: "சார்பு: யார் விடுபடலாம் அல்லது யாருக்கு அநீதி நடக்கலாம்?",
    q_eth_safety: "பாதுகாப்பு: என்ன தவறு நடக்கலாம், உங்கள் மாற்றுத் திட்டம் என்ன?",
    print_blank: "வெற்றுப் பணித்தாளை அச்சிடு",
    download_txt: "உரைக் கோப்பாகப் பதிவிறக்கு",
    empty_field: "— இன்னும் நிரப்பவில்லை —",
