    st6: "వాడకంలోకి తేవడం",
    st7: "నైతికత తనిఖీ",
    st8: "పూర్తి కాన్వాస్",
    st1_d: "AI గురించి ఆలోచించే ముందు సమస్యను బాగా అర్థం చేసుకోండి. 4W కాన్వాస్ వాడండి: ఎవరు, ఏమిటి, ఎక్కడ, ఎందుకు.",
    st2_d: "ఏ డేటా కావాలో, అది ఎక్కడి నుంచి వస్తుందో నిర్ణయించండి. మంచి AI మోడల్‌కు మంచి, నమ్మదగిన డేటా అవసరం.",
    st3_d: "ప్యాటర్న్‌లు, తప్పులు, ఆశ్చర్యకర విషయాలు కనిపించేలా చార్టులతో డేటాను ఎలా పరిశీలిస్తారో ప్లాన్ చేయండి.",
    st4_d: "యంత్రం ఎలా నిర్ణయం తీసుకుంటుందో ఎంచుకోండి: మనుషులు రాసిన నియమాలతోనా, లేక చాలా ఉదాహరణల నుంచి నేర్చుకునా.",
    st5_d: "మోడల్ ఎప్పుడూ చూడని కొత్త డేటాపై దాన్ని పరీక్షించండి, విజయాన్ని ఎలా కొలుస్తారో నిర్ణయించండి.",
