    eth_todo: "టిక్ చేయని అంశాల గురించి బృందంతో చర్చించి, మీ ప్రణాళికను మెరుగుపరచండి.",
    q_eth_privacy: "గోప్యత: ఏ వ్యక్తిగత డేటా ఉంది, దాన్ని మీరు ఎలా కాపాడతారు?",
    q_eth_bias: "పక్షపాతం: ఎవరు వదిలివేయబడవచ్చు లేదా ఎవరికి అన్యాయం జరగవచ్చు?",
    q_eth_safety: "భద్రత: ఏం తప్పు జరగవచ్చు, మీ ప్రత్యామ్నాయ ప్రణాళిక ఏమిటి?",
