    stage_done: "ಪೂರ್ಣಗೊಂಡಿದೆ",
    st1: "ಸಮಸ್ಯೆ ಗುರುತಿಸುವಿಕೆ",
    st2: "ಡೇಟಾ ಸಂಗ್ರಹ",
