    st8: "ಪೂರ್ಣ ಕ್ಯಾನ್ವಾಸ್",
    st1_d: "AI ಬಗ್ಗೆ ಯೋಚಿಸುವ ಮೊದಲು ಸಮಸ್ಯೆಯನ್ನು ಚೆನ್ನಾಗಿ ಅರಿಯಿರಿ. 4W ಕ್ಯಾನ್ವಾಸ್ ಬಳಸಿ: ಯಾರು, ಏನು, ಎಲ್ಲಿ ಮತ್ತು ಏಕೆ.",
    st2_d: "ಯಾವ ಡೇಟಾ ಬೇಕು ಮತ್ತು ಅದು ಎಲ್ಲಿಂದ ಬರುತ್ತದೆ ಎಂದು ನಿರ್ಧರಿಸಿ. ಉತ್ತಮ AI ಮಾದರಿಗೆ ಉತ್ತಮ, ನಂಬಲರ್ಹ ಡೇಟಾ ಬೇಕು.",
    st3_d: "ಮಾದರಿ ರೂಪಗಳು, ತಪ್ಪುಗಳು ಮತ್ತು ಅಚ್ಚರಿಗಳು ಕಾಣುವಂತೆ ಚಾರ್ಟ್‌ಗಳಿಂದ ಡೇಟಾವನ್ನು ಹೇಗೆ ಪರಿಶೀಲಿಸುವಿರಿ ಎಂದು ಯೋಜಿಸಿ.",
    st4_d: "ಯಂತ್ರ ಹೇಗೆ ನಿರ್ಧರಿಸುತ್ತದೆ ಎಂದು ಆರಿಸಿ: ಜನರು ಬರೆದ ನಿಯಮಗಳಿಂದ, ಅಥವಾ ಹಲವು ಉದಾಹರಣೆಗಳಿಂದ ಕಲಿತು.",
    st5_d: "ಮಾದರಿ ಎಂದೂ ನೋಡದ ಹೊಸ ಡೇಟಾದ ಮೇಲೆ ಅದನ್ನು ಪರೀಕ್ಷಿಸಿ, ಯಶಸ್ಸನ್ನು ಹೇಗೆ ಅಳೆಯುವಿರಿ ಎಂದು ನಿರ್ಧರಿಸಿ.",
    st6_d: "ನಿಜವಾದ ಜನರು ನಿಮ್ಮ ಪರಿಹಾರವನ್ನು ಹೇಗೆ ಬಳಸುತ್ತಾರೆ ಮತ್ತು ಅದನ್ನು ಯಾರು ನೋಡಿಕೊಳ್ಳುತ್ತಾರೆ ಎಂದು ಯೋಜಿಸಿ.",
    st7_d: "ನಿಮ್ಮ ಪ್ರಾಜೆಕ್ಟ್ ಖಾಸಗಿತನವನ್ನು ಗೌರವಿಸುತ್ತದೆಯೇ, ಎಲ್ಲರಿಗೂ ನ್ಯಾಯಯುತವೇ ಮತ್ತು ಸುರಕ್ಷಿತವೇ ಎಂದು ಪರಿಶೀಲಿಸಿ.",
    st8_d: "ಇಡೀ ಪ್ರಾಜೆಕ್ಟ್ ಒಂದೇ ಪುಟದಲ್ಲಿ: ನೋಡಿ, ಮುದ್ರಿಸಿ, ಡೌನ್‌ಲೋಡ್ ಮಾಡಿ ಅಥವಾ ಪ್ರಸ್ತುತಪಡಿಸಿ.",
