    q_deploy_care: "ಇದನ್ನು ಯಾರು ನೋಡಿಕೊಳ್ಳುತ್ತಾರೆ? ಅಭಿಪ್ರಾಯ ಹೇಗೆ ಸಂಗ್ರಹಿಸಿ ಇದನ್ನು ಸುಧಾರಿಸುತ್ತೀರಿ?",
    eth_checks_h: "ನೈತಿಕತೆ ಪರಿಶೀಲನಾ ಪಟ್ಟಿ: ನಿಮ್ಮ ಪ್ರಾಜೆಕ್ಟ್‌ಗೆ ನಿಜವಾದವುಗಳಿಗೆ ಟಿಕ್ ಮಾಡಿ",
    ec1: "ನಿಜವಾಗಿಯೂ ಬೇಕಾದಷ್ಟು ಡೇಟಾವನ್ನು ಮಾತ್ರ ನಾವು ಸಂಗ್ರಹಿಸುತ್ತೇವೆ.",
    ec2: "ಡೇಟಾ ಸಂಗ್ರಹಿಸುವ ಮೊದಲು ಜನರು ಅನುಮತಿ (ಒಪ್ಪಿಗೆ) ನೀಡುತ್ತಾರೆ.",
    ec3: "ವೈಯಕ್ತಿಕ ಡೇಟಾವನ್ನು ಸುರಕ್ಷಿತವಾಗಿ ಇಡಲಾಗುತ್ತದೆ, ಯಾರೊಂದಿಗೂ ಹಂಚಿಕೊಳ್ಳುವುದಿಲ್ಲ.",
    ec4: "ನಮ್ಮ ಡೇಟಾದಲ್ಲಿ ಎಲ್ಲಾ ರೀತಿಯ ಜನರಿದ್ದಾರೆ: ಹುಡುಗಿಯರು ಮತ್ತು ಹುಡುಗರು, ಹಳ್ಳಿಗಳು ಮತ್ತು ನಗರಗಳು, ಬೇರೆ ಬೇರೆ ಭಾಷೆಗಳು.",
    ec5: "ಮಾದರಿ ಬೇರೆ ಬೇರೆ ಗುಂಪುಗಳಿಗೆ ಸಮಾನವಾಗಿ ಚೆನ್ನಾಗಿ ಕೆಲಸ ಮಾಡುತ್ತದೆಯೇ ಎಂದು ಪರೀಕ್ಷಿಸುತ್ತೇವೆ.",
    ec6: "ಮುಖ್ಯ ನಿರ್ಧಾರಗಳನ್ನು ಒಬ್ಬ ವ್ಯಕ್ತಿ ಪರಿಶೀಲಿಸುತ್ತಾರೆ; AI ಒಂಟಿಯಾಗಿ ನಿರ್ಧರಿಸುವುದಿಲ್ಲ.",
    ec7: "AI ಬಳಸಲಾಗುತ್ತಿದೆ ಮತ್ತು ಅದು ಏನು ಮಾಡುತ್ತದೆ ಎಂದು ಬಳಕೆದಾರರಿಗೆ ತಿಳಿಸಲಾಗುತ್ತದೆ.",
    ec8: "ಏನು ತಪ್ಪಾಗಬಹುದು ಮತ್ತು ಹಾನಿಯನ್ನು ಹೇಗೆ ತಡೆಯುವುದು ಎಂದು ನಾವು ಯೋಚಿಸಿದ್ದೇವೆ.",
    eth_score: "{total} ರಲ್ಲಿ {n} ಟಿಕ್ ಆಗಿವೆ",
    eth_ok: "ಭೇಷ್! ನಿಮ್ಮ ಪ್ರಾಜೆಕ್ಟ್ ನೈತಿಕತೆ ಪರಿಶೀಲನೆಯಲ್ಲಿ ಉತ್ತೀರ್ಣವಾಗಿದೆ.",
    eth_todo: "ಟಿಕ್ ಆಗದ ಅಂಶಗಳ ಬಗ್ಗೆ ತಂಡದೊಂದಿಗೆ ಚರ್ಚಿಸಿ, ನಿಮ್ಮ ಯೋಜನೆಯನ್ನು ಸುಧಾರಿಸಿ.",
    q_eth_privacy: "ಖಾಸಗಿತನ: ಯಾವ ವೈಯಕ್ತಿಕ ಡೇಟಾ ಇದೆ, ಮತ್ತು ಅದನ್ನು ಹೇಗೆ ರಕ್ಷಿಸುತ್ತೀರಿ?",
    q_eth_bias: "ಪಕ್ಷಪಾತ: ಯಾರು ಹೊರಗುಳಿಯಬಹುದು ಅಥವಾ ಯಾರಿಗೆ ಅನ್ಯಾಯವಾಗಬಹುದು?",
    q_eth_safety: "ಸುರಕ್ಷತೆ: ಏನು ತಪ್ಪಾಗಬಹುದು, ಮತ್ತು ನಿಮ್ಮ ಪರ್ಯಾಯ ಯೋಜನೆ ಏನು?",
    print_blank: "ಖಾಲಿ ವರ್ಕ್‌ಶೀಟ್ ಮುದ್ರಿಸಿ",
