    st3_d: "പാറ്റേണുകളും തെറ്റുകളും അതിശയങ്ങളും കാണാൻ ചാർട്ടുകൾ വഴി ഡാറ്റ എങ്ങനെ പരിശോധിക്കുമെന്ന് ആസൂത്രണം ചെയ്യുക.",
    st4_d: "യന്ത്രം എങ്ങനെ തീരുമാനമെടുക്കുമെന്ന് തിരഞ്ഞെടുക്കുക: ആളുകൾ എഴുതുന്ന നിയമങ്ങളാലോ, അനേകം ഉദാഹരണങ്ങളിൽ നിന്ന് പഠിച്ചോ.",
    st5_d: "മോഡൽ ഇതുവരെ കാണാത്ത പുതിയ ഡാറ്റയിൽ അത് പരീക്ഷിക്കുക, വിജയം എങ്ങനെ അളക്കുമെന്ന് തീരുമാനിക്കുക.",
    st6_d: "യഥാർത്ഥ ആളുകൾ നിങ്ങളുടെ പരിഹാരം എങ്ങനെ ഉപയോഗിക്കുമെന്നും ആര് അത് പരിപാലിക്കുമെന്നും ആസൂത്രണം ചെയ്യുക.",
    st7_d: "നിങ്ങളുടെ പ്രോജക്റ്റ് സ്വകാര്യതയെ മാനിക്കുന്നുണ്ടോ, എല്ലാവരോടും നീതിപുലർത്തുന്നുണ്ടോ, സുരക്ഷിതമാണോ എന്ന് പരിശോധിക്കുക.",
